public IQueryable<Order> PaidOrders(AppDb db) =>
    db.Orders.Where(o => o.Status == "paid");

public async Task<List<Order>> TopToday(AppDb db, CancellationToken ct) =>
    await PaidOrders(db)
        .Where(o => o.CreatedAt >= DateTime.UtcNow.Date)
        .OrderByDescending(o => o.Total)
        .Take(10)
        .ToListAsync(ct);
// EF traduz tudo em 1 SQL: WHERE Status='paid' AND CreatedAt>=... ORDER BY Total DESC LIMIT 10

